<script setup lang="ts">
import { useFeedback } from '../feedback';
import { markDirty } from '../workspace';
import { formatBeijing,stateLabel,roleNames,rolesText,actionLabel } from '../presentation';
import { ref,onMounted } from 'vue';
import { listDepartments,type Department } from '../api';
import { courseApi,errorText,tag,type User,type Employee,type Page } from '../course-api';
const items=ref<User[]>([]),employees=ref<Employee[]>([]),departments=ref<Department[]>([]),q=ref(''),page=ref(1),total=ref(0),busy=ref(false),error=ref(''),notice=ref(''),open=ref(false),selected=ref<User|null>(null),reset=ref<User|null>(null),password=ref('');
const blank=()=>({username:'',password:'',employee_id:null as string|null,roles:['EMPLOYEE'],department_ids:[] as string[],status:'ACTIVE'});
const form=ref(blank());
const audits=ref<{id:string;occurred_at:string;action_code:string;outcome:string;request_id:string;actor_user_id:string|null;actor_username?:string|null}[]>([]),auditPage=ref(1),auditTotal=ref(0);
async function loadAudit(){error.value='';try{const data=await courseApi<Page<typeof audits.value[number]>>(`/users/audit-events?page=${auditPage.value}&page_size=20`);audits.value=data.items;auditTotal.value=data.total;}catch(e){error.value=errorText(e);}}
async function load(){busy.value=true;error.value='';try{const data=await courseApi<Page<User>>(`/users?q=${encodeURIComponent(q.value)}&page=${page.value}&page_size=20`);items.value=data.items;total.value=data.total;}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
function edit(row?:User){selected.value=row||null;form.value=row?{username:row.username,password:'',employee_id:row.employee_id,roles:[...row.roles],department_ids:[...row.department_ids],status:row.status}:blank();open.value=true;reset.value=null;}
async function save(){busy.value=true;error.value='';notice.value='';try{const {username,password,...rest}=form.value;
  if(selected.value)await courseApi(`/users/${encodeURIComponent(selected.value.id)}`,'PATCH',rest,tag(selected.value));
  else await courseApi('/users','POST',{username,password,employee_id:rest.employee_id,roles:rest.roles,department_ids:rest.department_ids});
  markDirty('/users',false);notice.value='账号已保存；角色或状态变更已撤销旧会话';open.value=false;await load();
}catch(e){error.value=errorText(e);}finally{form.value.password='';busy.value=false;}}
async function savePassword(){if(!reset.value)return;busy.value=true;error.value='';notice.value='';try{await courseApi(`/users/${encodeURIComponent(reset.value.id)}/password`,'POST',{password:password.value},tag(reset.value));markDirty('/users',false,'password');notice.value='密码已重置，旧会话已撤销';reset.value=null;await load();}catch(e){error.value=errorText(e);}finally{password.value='';busy.value=false;}}
onMounted(async()=>{try{await load();let p=1;for(;;){const data=await courseApi<Page<Employee>>(`/users/employee-options?page=${p}&page_size=100`);employees.value.push(...data.items);if(employees.value.length>=data.total)break;p++;}p=1;for(;;){const data=await listDepartments('',p,100);departments.value.push(...data.items);if(departments.value.length>=data.total)break;p++;}}catch(e){error.value=errorText(e);}});
useFeedback(notice,error,'/users');
</script>
<template><div class="business-page"><main><div class="section-heading"><h1>用户管理</h1><button :disabled="busy" @click="edit()">创建账号</button></div><p class="muted">仅 ADMIN 管理。业务角色须绑定有效员工；不能修改本人角色或停用本人。ADMIN 不自动拥有 HR 权限。</p><p v-if="error" class="error feedback" role="alert">{{error}}</p><p v-if="notice" class="success feedback" role="status">{{notice}}</p>
<section class="card"><form class="search-row" @submit.prevent="page=1;load()"><label>账号搜索<input v-model="q" maxlength="64"></label><button :disabled="busy">查询</button></form><p v-if="busy" role="status">加载中…</p><p v-else-if="!items.length" class="muted">没有匹配账号。</p><div v-else class="table-scroll"><table><thead><tr><th>账号</th><th>员工</th><th>有效角色</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="row in items" :key="row.id"><td>{{row.username}}</td><td>{{employees.find(e=>e.id===row.employee_id)?(employees.find(e=>e.id===row.employee_id)?.full_name+' · '+employees.find(e=>e.id===row.employee_id)?.employee_no):'未绑定员工'}}</td><td>{{rolesText(row.roles)}}</td><td>{{row.status==='ACTIVE'?'启用':'停用'}}</td><td><button class="text-button" :disabled="busy" @click="edit(row)">编辑 / 角色 / 停用</button><button class="text-button" :disabled="busy" @click="reset=row;open=false;password=''">重置密码</button></td></tr></tbody></table></div><nav class="pagination"><span>共 {{total}} 条</span><button :disabled="busy||page<=1" @click="page--;load()">上一页</button><button :disabled="busy||page*20>=total" @click="page++;load()">下一页</button></nav></section>
<section v-if="open" class="card"><h2>{{selected?'编辑账号':'创建账号'}}</h2><form @submit.prevent="save"><fieldset :disabled="busy"><div class="form-columns"><label>账号<input v-model="form.username" required maxlength="64" :disabled="!!selected" autocomplete="off"></label><label v-if="!selected">初始密码<input v-model="form.password" type="password" required minlength="12" maxlength="128" autocomplete="new-password"></label><label>绑定员工<select aria-label="绑定员工" v-model="form.employee_id"><option :value="null">不绑定（仅 ADMIN）</option><option v-for="e in employees" :key="e.id" :value="e.id">{{e.employee_no}} · {{e.full_name}} · {{stateLabel(e.employment_status)}}</option></select></label><label v-if="selected">状态<select aria-label="状态" v-model="form.status"><option value="ACTIVE">启用</option><option value="DISABLED">停用</option></select></label></div><h3>基础角色</h3><div class="checks"><label v-for="role in ['EMPLOYEE','MANAGER','HR','ADMIN']" :key="role"><input v-model="form.roles" type="checkbox" :value="role" :aria-label="role">{{roleNames[role]}}</label></div><template v-if="form.roles.includes('MANAGER')"><h3>直接负责部门</h3><div class="checks"><label v-for="d in departments.filter(x=>x.status==='ACTIVE')" :key="d.id"><input v-model="form.department_ids" type="checkbox" :value="d.id">{{d.name}}</label></div></template><p class="muted">移除 MANAGER 时请先取消负责部门。角色变更与账号停用会撤销该账号全部旧会话。</p><div class="form-actions"><button>保存账号</button><button type="button" class="secondary" data-clear-dirty @click="open=false;form.password=''">取消</button></div></fieldset></form></section>
<section v-if="reset" class="card"><h2>重置 {{reset.username}} 的密码</h2><form data-dirty-scope="password" @submit.prevent="savePassword"><label>新密码<input v-model="password" type="password" required minlength="12" maxlength="128" autocomplete="new-password"></label><div class="form-actions"><button :disabled="busy">重置并撤销旧会话</button><button type="button" class="secondary" data-clear-dirty="password" @click="reset=null;password=''">取消</button></div></form></section>
<section class="card"><div class="section-heading"><h2>重要操作审计</h2><button class="secondary" @click="loadAudit">读取审计</button></div><p class="muted">仅展示动作、结果和追踪标识；不返回密码、令牌或工资明文。</p><div v-if="audits.length" class="table-scroll"><table><thead><tr><th>北京时间 / 操作</th><th>操作者</th><th>结果 / 请求ID</th></tr></thead><tbody><tr v-for="event in audits" :key="event.id"><td>{{formatBeijing(event.occurred_at)}}<br>{{actionLabel(event.action_code)}}</td><td><small>{{event.actor_username||'系统 / 未认证事件'}}</small></td><td>{{stateLabel(event.outcome)}}<br><small>{{event.request_id}}</small></td></tr></tbody></table></div><nav v-if="auditTotal" class="pagination"><span>共 {{auditTotal}} 条</span><button :disabled="auditPage<=1" @click="auditPage--;loadAudit()">上一页</button><button :disabled="auditPage*20>=auditTotal" @click="auditPage++;loadAudit()">下一页</button></nav></section>
</main></div></template>
